new file mode 100644
index 0000000..736cc45
--- /dev/null
+++ b/source/standalone/largest-http2-timeout.ts
@@ -0,0 +1,23 @@
+type TimeoutRecord = {
+	socket?: unknown;
+	connect?: unknown;
+	lookup?: unknown;
+	request?: unknown;
+	secureConnect?: unknown;
+};
+
+type Http2TimeoutInternals = {
+	timeout: TimeoutRecord;
+};
+
+export const largestHttp2Timeout = (internals: Http2TimeoutInternals): number | undefined => {
+	const delays = [internals.timeout.socket, internals.timeout.connect, internals.timeout.lookup, internals.timeout.request, internals.timeout.secureConnect].filter((delay): delay is number => typeof delay === 'number');
+
+	if (delays.length > 0) {
+		return Math.max(...delays);
+	}
+
+	return undefined;
+};
+
+export default largestHttp2Timeout;
diff --git a/test/largest-http2-timeout.ts b/test/largest-http2-timeout.ts
new file mode 100644
index 0000000..5f7ff39
--- /dev/null
+++ b/test/largest-http2-timeout.ts
@@ -0,0 +1,28 @@
+import test from 'ava';
+import {largestHttp2Timeout} from '../source/standalone/largest-http2-timeout.js';
+
+test('returns the largest numeric delay', t => {
+	t.is(largestHttp2Timeout({timeout: {socket: 30, connect: 10, lookup: 50, request: 20, secureConnect: 40}}), 50);
+});
+
+test('ignores non-numeric entries', t => {
+	t.is(largestHttp2Timeout({timeout: {socket: undefined, connect: 5, lookup: '100', request: null, secureConnect: 3}}), 5);
+});
+
+test('ignores timeout entries that are not read', t => {
+	const timeout: Record<string, unknown> = {connect: 1, response: 1000, send: 500, read: 2000};
+	t.is(largestHttp2Timeout({timeout}), 1);
+});
+
+test('returns undefined when there are no numeric entries', t => {
+	t.is(largestHttp2Timeout({timeout: {}}), undefined);
+	t.is(largestHttp2Timeout({timeout: {socket: undefined, request: undefined}}), undefined);
+});
+
+test('handles a single numeric entry', t => {
+	t.is(largestHttp2Timeout({timeout: {request: 0}}), 0);
+});
+
+test('throws when timeout is missing', t => {
+	t.throws(() => largestHttp2Timeout({} as any), {instanceOf: TypeError});
+});
